SELECT FLOOR(UNIX_TIMESTAMP(observed_at)) AS sec, COUNT(*) AS n_events, COUNT(DISTINCT symbol) AS n_symbols, SUM(symbol='EGLDUSDT') AS egld, SUM(delivery_status NOT IN ('APPLIED','LEGACY')) AS non_applied, ROUND(MAX(UNIX_TIMESTAMP(created_at)-UNIX_TIMESTAMP(observed_at)),3) AS max_lag_s FROM crypto_ai.market_price_event WHERE observed_at BETWEEN FROM_UNIXTIME(1791747598) AND FROM_UNIXTIME(1791747840) GROUP BY sec ORDER BY sec LIMIT 260;
SELECT COUNT(DISTINCT symbol) AS symbols_in_window FROM crypto_ai.market_price_event WHERE observed_at BETWEEN FROM_UNIXTIME(1791747598) AND FROM_UNIXTIME(1791747840);